27	+// Newlib's <sys/_default_fcntl.h> uses BSD-derived O_* values that differ
28	+// from the Linux ABI -- e.g. O_CREAT=0x200 in newlib vs 0x40 in Linux,
29	+// O_TRUNC=0x400 vs 0x200. Pass-through to host open() with newlib values
30	+// would clear O_CREAT/O_EXCL and silently accept O_APPEND, so a fopen("w+")
31	+// for a non-existent file fails with ENOENT. Translate flag-by-flag.
32	+inline int newlib_to_linux_open_flags(uint64_t newlib_flags)
33	+{
34	+  constexpr uint64_t NL_RDONLY  = 0;
35	+  constexpr uint64_t NL_WRONLY  = 1;
36	+  constexpr uint64_t NL_RDWR    = 2;
37	+  constexpr uint64_t NL_APPEND  = 0x0008;
38	+  constexpr uint64_t NL_CREAT   = 0x0200;
39	+  constexpr uint64_t NL_TRUNC   = 0x0400;
40	+  constexpr uint64_t NL_EXCL    = 0x0800;
41	+  constexpr uint64_t NL_NONBLOCK = 0x4000;
42	+  constexpr uint64_t NL_NOCTTY  = 0x8000;
43	+
44	+  int linux_flags = 0;
45	+  switch (newlib_flags & 3) {
46	+    case NL_RDONLY: linux_flags |= O_RDONLY; break;
47	+    case NL_WRONLY: linux_flags |= O_WRONLY; break;
48	+    case NL_RDWR:   linux_flags |= O_RDWR;   break;
49	+  }
50	+  if (newlib_flags & NL_APPEND)   linux_flags |= O_APPEND;
51	+  if (newlib_flags & NL_CREAT)    linux_flags |= O_CREAT;
52	+  if (newlib_flags & NL_TRUNC)    linux_flags |= O_TRUNC;
53	+  if (newlib_flags & NL_EXCL)     linux_flags |= O_EXCL;
54	+  if (newlib_flags & NL_NONBLOCK) linux_flags |= O_NONBLOCK;
55	+  if (newlib_flags & NL_NOCTTY)   linux_flags |= O_NOCTTY;
56	+  return linux_flags;
57	+}
