306	  // skip_memory_load: parse the ELF and set the reset vector, but leave
307	  // platform.main_memory untouched. Used in tier-2 hybrid resume where
308	  // QEMU 1's -kernel already populated the shared mmap; re-loading would
309	  // zero-fill the .bss tail of each PT_LOAD and destroy phase-1 writes
310	  // to static buffers. The reset vector is still set so the hart has a
311	  // valid fetch target during the post-reset cycles that precede the DMI
312	  // halt+DPC-write resume sequence.
313	  void load_elf(const std::string& path, bool skip_memory_load = false)
314	  {
315	    const auto elf = LIEF::ELF::Parser::parse(path);
316	    if (!elf) {
317	      spdlog::critical("Check if it's a valid ELF file path : {}", path);
318	      exit(1);
319	    }
320	
321	    if (!skip_memory_load)
322	      read_elf_into_memory(
323	        *elf,
324	        static_cast<xlen_t>(platform.main_memory.region.base_address),
325	        platform.main_memory.data);
326	    for (auto& rv: platform.reset_vector)
327	      rv.write(elf->entrypoint());
328	  }
