330	  void set_reset_vector(size_t hart, uint64_t addr)
331	  {
332	    if (hart >= platform.reset_vector.size()) {
333	      spdlog::critical("hart {} out of range (max {})", hart,
334	                       platform.reset_vector.size() - 1);
335	      std::exit(EXIT_FAILURE);
336	    }
337	    platform.reset_vector[hart].write(addr);
338	  }
